    36	// Resolves the spec's open question on "alike" -- exactly the same type, or
    37	// just the same family? -- in favour of identical type. The spec's
    38	// mixed-component examples decide it; the specs assert them.
    39	function groupAlikeItems(items: readonly Item[]): Map<string, number> {
    40	  const counts = new Map<string, number>();
    41	  for (const item of items) {
    42	    counts.set(item.type, (counts.get(item.type) ?? 0) + 1);
    43	  }
    44	  return counts;
    45	}
