    51	// Eligibility for the building-block offer, resolving two spec readings:
    52	//   - exactly ALIKE_BLOCK_SIZE, not repeating within a larger count -- the
    53	//     spec's 4-rune and 7-rune examples rule out charging a second block;
    54	//   - components only -- the spec offers the block for "3 alike components",
    55	//     so three swords are three swords.
    56	// The specs assert all of these.
    57	function formsAlikeBlock(type: string, count: number): boolean {
    58	  return count === ALIKE_BLOCK_SIZE && isComponent(type);
    59	}
