    61	// The price-list tariff for a single item of this type, before any
    62	// building-block offer and before any item-specific surcharge.
    63	function itemBasePremium(type: string): number {
    64	  return BASE_PREMIUM_G[type];
    65	}
    66	
    67	function alikeItemsBasePremium(type: string, count: number): number {
    68	  if (formsAlikeBlock(type, count)) {
    69	    return ALIKE_BLOCK_BASE_PREMIUM_G;
    70	  }
    71	  return count * itemBasePremium(type);
    72	}
