    74	export function policyBasePremium(items: readonly Item[]): number {
    75	  let total = 0;
    76	  for (const [type, count] of groupAlikeItems(items)) {
    77	    total += alikeItemsBasePremium(type, count);
    78	  }
    79	  return total;
