    98	// The risk the MHPCO prices into one individual item. The spec lists two such
    99	// surcharges (curse, high enchantment) and its threshold examples state that
   100	// they stack additively on the same base, so this is the one place a new
   101	// item-level risk clause is declared.
   102	function itemRiskSurcharge(item: Item): number {
   103	  let rate = 0;
   104	  if (item.cursed === true) {
   105	    rate += CURSE_SURCHARGE_RATE;
   106	  }
   107	  if (isHighlyEnchanted(item)) {
   108	    rate += HIGH_ENCHANTMENT_SURCHARGE_RATE;
   109	  }
   110	  return itemBasePremium(item.type) * rate;
   111	}
