   113	// The premium stage between the two modifier scopes the spec distinguishes:
   114	// item-specific surcharges have been applied to the base premium of each
   115	// affected item; policy-wide modifiers and the fee have not been applied yet.
   116	export function premiumAfterItemModifiers(items: readonly Item[]): number {
   117	  let total = policyBasePremium(items);
   118	  for (const item of items) {
   119	    total += itemRiskSurcharge(item);
   120	  }
   121	  return total;
   122	}
